const camera=new T.PerspectiveCamera(43,1,.1,120);const target=new T.Vector3(0,1,0),eye=new T.Vector3(14,12,18);camera.position.copy(eye);
scene.add(new T.HemisphereLight('#eaf5ff','#756348',2));const sun=new T.DirectionalLight('#ffe4af',3.4);sun.position.set(6,18,8);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-20,right:20,top:20,bottom:-20,near:1,far:60});sun.shadow.normalBias=.04;scene.add(sun);
const mat=(c,rough=.8)=>new T.MeshStandardMaterial({color:c,roughness:rough});const wood=mat('#886049'),gold=mat('#c8a264',.35),green=mat('#345d4f'),cream=mat('#e9d6ab'),red=mat('#9a3d52'),snow=mat('#eff5ec'),iron=mat('#344c50');
