box(3.4,3,.25,cream,-4,3.3,-5.63);box(3,2.6,.28,windowGlass,-4,3.3,-5.45);for(let x of [-5,-4,-3])box(.07,2.6,.4,cream,x,3.3,-5.28);box(3,.08,.4,cream,-4,3.3,-5.28);box(4,.17,.8,wood,-4,1.85,-5.3);
