for(let i=0;i<7;i++)box(.3,.15,.8,mat(['#6a3544','#a68149','#38635b'][i%3]),-4.8+i*.3,2+i*.025,-2.2);
for(let x of [-5.4,-2.6]){cyl(.13,.22,.14,gold,x,2,-1.8);cyl(.07,.07,.55,cream,x,2.35,-1.8);const f=sphere(.1,mat('#ffd886'),x,2.68,-1.8);f.material.emissive=new T.Color('#ffb244');f.material.emissiveIntensity=2;}
const shelf=new T.Group();scene.add(shelf);for(let x of [.1,3.4])box(.18,4.4,.8,wood,x,2.2,-5.2,shelf);for(let y of [.4,1.6,2.8,4.2])box(3.5,.15,1,wood,1.7,y,-5.2,shelf);for(let i=0;i<23;i++)box(.17,.5+(i%3)*.1,.4,mat(['#406859','#7b4250','#b19b6a'][i%3]),.25+(i%11)*.28,1.95+Math.floor(i/11)*1.2,-5.15,shelf);
